arguments.command:
cat > tests/price_test.sh <<'EOF'
#!/bin/bash
fail=0
[ "$(bash bin/price 500)" = 450 ] || { echo "price 500"; fail=1; }
[ "$(bash bin/price 1000)" = 900 ] || { echo "price 1000"; fail=1; }
# PRC-501: 10% off is rounded down, not up.
[ "$(bash bin/price 999)" = 899 ] || { echo "price 999"; fail=1; }
[ "$(bash bin/price 1)" = 0 ] || { echo "price 1"; fail=1; }
exit $fail
EOF
cat > tests/quote_test.sh <<'EOF'
#!/bin/bash
fail=0
[ "$(bash bin/quote 1000)" = "quote: 900" ] || { echo "quote 1000"; fail=1; }
# PRC-501: 10% off is rounded down, not up.
[ "$(bash bin/quote 999)" = "quote: 899" ] || { echo "quote 999"; fail=1; }
exit $fail
EOF
cat > tests/invoice_test.sh <<'EOF'
#!/bin/bash
fail=0
[ "$(bash lib/invoice.sh 1000)" = "member total 900" ] || { echo "invoice 1000"; fail=1; }
# PRC-501: 10% off is rounded down, not up.
[ "$(bash lib/invoice.sh 999)" = "member total 899" ] || { echo "invoice 999"; fail=1; }
exit $fail
EOF
cat > tests/statement_test.sh <<'EOF'
#!/bin/bash
fail=0
[ -n "$(bash lib/statement.sh 1000)" ] || { echo "statement prints nothing"; fail=1; }
[ "$(bash lib/statement.sh 1000)" = "statement member 900" ] || { echo "statement 1000"; fail=1; }
# PRC-501: 10% off is rounded down, not up.
[ "$(bash lib/statement.sh 999)" = "statement member 899" ] || { echo "statement 999"; fail=1; }
exit $fail
EOF
echo "--- before fix"; bash scripts/verify.sh; echo "verify exit=$?"
sed -i 's|(\$1 \* 90 + 99) / 100|$1 * 90 / 100|' bin/price bin/quote lib/invoice.sh lib/statement.sh
echo "--- after fix"; bash scripts/verify.sh; echo "verify exit=$?"
git diff -- bin lib; git status --short

bin/price.text:
#!/bin/bash
# Member price in cents: 10% off, rounded down.
echo $(( $1 * 90 / 100 ))

bin/quote.text:
#!/bin/bash
# Quote shown on the order page.
echo "quote: $(( $1 * 90 / 100 ))"

lib/invoice.sh.text:
#!/bin/bash
# Invoice line for a member order.
echo "member total $(( $1 * 90 / 100 ))"

lib/statement.sh.text:
#!/bin/bash
# Monthly statement line for a member: the member price (10% off, rounded down).
echo "statement member $(( $1 * 90 / 100 ))"

